	public static class StringExtensions
	{
		private static readonly int _charactersPerWord = 4;

		public static int[] Holleriths(this string str, int minimumWords = 0)
		{
			int val = (str.Length + _charactersPerWord - 1) / _charactersPerWord;
			int[] array = new int[Math.Max(minimumWords, val)];
			int num = 0;
			int i = 1;
			int num2 = 0;
			foreach (char c in str)
			{
				num2 *= 256;
				num2 += c;
				if (i == _charactersPerWord)
				{
					array[num++] = num2;
					num2 = 0;
					i = 0;
				}
				i++;
			}
			if (i != 1)
			{
				for (; i < 5; i++)
				{
					num2 *= 256;
					num2 += 32;
				}
				array[num++] = num2;
			}
			while (num < minimumWords)
			{
				array[num++] = 538976288;
			}
			return array;
		}
	}
