	public class ArraySentenceDefinition : SentenceDefinitionBase
	{
		public override string Structure => "Array";

		public override void DefaultSentence(int integerOffset, int realOffset)
		{
			base.Variables.ToList().ForEach(delegate
			{
				_fixedIntegerArray.Add(0);
			});
			_fixedIntegerArray.Add(0);
			_variableIntegerArray.Clear();
			_fixedRealArray.Clear();
			_variableRealArray.Clear();
		}

		public override void DefaultSentence(int integerOffset, int realOffset, IAspenProblemData caseData)
		{
			DefaultSentence(integerOffset, realOffset);
		}

		public override void ProcessSentence(IList<ISentenceSpecification> sentences, int integerOffset, int realOffset)
		{
			_integerOffset = integerOffset;
			_realOffset = realOffset;
			_numberOfSentences = sentences.Count;
			foreach (IVariableDefinition variableDefinition in base.Variables)
			{
				_storeIndex = true;
				foreach (ISentenceSpecification sentence in sentences)
				{
					if (sentence.Variables.Any((IVariableSpecification v) => v.Name == variableDefinition.TKWName))
					{
						IVariableSpecification variableSpecification = sentence.Variables.First((IVariableSpecification v) => MatchVariableNames(variableDefinition, v.Name));
						ProcessVariableSpecification(variableDefinition, variableSpecification);
					}
					else
					{
						ProcessVariableDefault(variableDefinition);
					}
				}
				StoreVectors();
			}
			_fixedIntegerArray.Add(_numberOfSentences);
			_integerOffset = 0;
			_realOffset = 0;
			_storeIndex = false;
		}

		public override void ProcessSentence(IList<ISentenceSpecification> sentences, int integerOffset, int realOffset, IAspenProblemData caseData)
		{
			_integerOffset = integerOffset;
			_realOffset = realOffset;
			_numberOfSentences = sentences.Count;
			foreach (IVariableDefinition variableDefinition in base.Variables)
			{
				_storeIndex = true;
				foreach (ISentenceSpecification sentence in sentences)
				{
					if (sentence.Variables.Any((IVariableSpecification v) => v.Name == variableDefinition.TKWName && v.Value != null))
					{
						IVariableSpecification variableSpecification = sentence.Variables.First((IVariableSpecification v) => MatchVariableNames(variableDefinition, v.Name));
						ProcessVariableSpecification(variableDefinition, variableSpecification);
					}
					else
					{
						ProcessVariableDefault(variableDefinition);
					}
				}
				StoreVectors();
			}
			_fixedIntegerArray.Add(_numberOfSentences);
			_integerOffset = 0;
			_realOffset = 0;
			_storeIndex = false;
		}
