		public void GenerateBeads()
		{
			if (BeadStatus.Ready == Status)
			{
				throw new AccessViolationException("Paragraph beads are already defined.");
			}
			if (BeadStatus.Modified == Status)
			{
				if (ParagraphList == null || ParagraphList.Count == 0)
				{
					Status = BeadStatus.Ready;
					return;
				}
				ParagraphList.Select((IParagraphSpecification x) => x.PKWName).ToList();
				IBeadData processBead = Parent.ProcessBead;
				IBeadData processBead2 = Parent.ProcessBead;
				(int, int) tuple = GenerateChemistryBead();
				RawInteger value = tuple.Item1;
				RawInteger value2 = tuple.Item2;
				processBead[107] = value;
				processBead2[108] = value2;
				processBead = Parent.ProcessBead;
				IBeadData processBead3 = Parent.ProcessBead;
				(int, int) tuple2 = GenerateReactionBead();
				value2 = tuple2.Item1;
				value = tuple2.Item2;
				processBead[196] = value2;
				processBead3[197] = value;
				processBead = Parent.ProcessBead;
				IBeadData processBead4 = Parent.ProcessBead;
				IBeadData processBead5 = Parent.ProcessBead;
				(int, int, int) tuple3 = GeneratePropertySetBead();
				value = tuple3.Item1;
