		internal string[] RearrangeVariableInSentenceArray(string[] sentenceInput, int currentIndex, IList<ISentenceDefinition> sentenceList, string[] sentenceArray, Dictionary<string, int> compAliasToIndex)
		{
			string text = sentenceInput[currentIndex].Split('=')[0];
			string text2 = sentenceInput[currentIndex].Split('=')[1];
			if (compAliasToIndex.ContainsKey(text2))
			{
				text2 = compAliasToIndex[text2].ToString();
			}
			ISentenceDefinition sentenceDefinition = sentenceList.FirstOrDefault((ISentenceDefinition sentenceInfo) => sentenceInfo.SKWName == sentenceInput[0]);
			int num = 1;
			foreach (IVariableDefinition variable in sentenceDefinition.Variables)
			{
				if (text == variable.TKWName)
				{
					if (sentenceInput[num] != null)
					{
						_ = sentenceInput[num];
					}
					sentenceArray[num] = text2;
					if (num != currentIndex)
					{
						sentenceArray[currentIndex] = null;
					}
					break;
				}
				num++;
			}
			return sentenceArray;
		}

		internal List<string[]> ConvertInputStringsToInt(Dictionary<string, int> compAliasToIndex, List<string[]> paragraphInput, IList<ISentenceDefinition> sentenceList)
		{
			List<string[]> list = new List<string[]>();
			foreach (string[] item in paragraphInput)
			{
				string[] array = new string[item.Length];
				Array.Copy(item, array, item.Length);
				for (int i = 0; i < item.Length; i++)
				{
					if (item[i] != null)
					{
						if (compAliasToIndex.ContainsKey(item[i]))
						{
							array[i] = compAliasToIndex[item[i]].ToString();
						}
						else if (item[i].Contains('='))
						{
							array = RearrangeVariableInSentenceArray(item, i, sentenceList, array, compAliasToIndex);
						}
						else
						{
							array[i] = item[i].Substring(item[i].LastIndexOf('=') + 1);
						}
					}
				}
				list.Add(array);
			}
			return list;
		}

