					int num2 = 9;
					int num3 = num2 + paragraph.GetIntegerLength();
					int realLength = paragraph.GetRealLength();
					IBeadData beadData2 = Parent.BeadFile.CreateBead(num3, realLength);
					beadData2[0] = 0L;
					if (beadData != null)
					{
						beadData[0] = beadData2.Id.RawNumber;
					}
					else
					{
						item = beadData2.Id.RawNumber;
					}
					item2 = beadData2.Id.RawNumber;
					beadData2[1] = num;
					beadData2[2] = 0L;
					beadData2[3] = WordUtility.FirstWord(paragraph2.ParagraphId);
					beadData2[4] = WordUtility.SecondWord(paragraph2.ParagraphId);
					beadData2[5] = paragraph.GetIntegerLength();
					beadData2[6] = num2;
					beadData2[7] = paragraph.GetRealLength();
					beadData2[8] = num3;
					for (int i = 0; i < integerArray.Length; i++)
					{
						beadData2[9 + i] = integerArray[i];
					}
					IBeadRealData beadRealData = (IBeadRealData)beadData2;
					for (int j = 0; j < realArray.Length; j++)
					{
						beadRealData[j] = realArray[j];
					}
					num = beadData2.Id.RawNumber;
					beadData = beadData2;
				}
			}
			return (item, item2);
		}

		private IParagraphSpecification CreateParagraph(IReactionTable paragraphDefinition, string pkwName, string Id, List<string[]> sentenceInputs)
		{
			Dictionary<string, SentenceDefinitionBase> dictionary = paragraphDefinition.Sentences.ToDictionary((ISentenceDefinition key) => key.SKWName, (ISentenceDefinition value) => (SentenceDefinitionBase)value);
			List<ISentenceSpecification> list = new List<ISentenceSpecification>();
			foreach (string[] sentenceInput in sentenceInputs)
			{
				list.Add(CreateSentences(sentenceInput[0], dictionary[sentenceInput[0]], sentenceInput.Skip(1).ToArray()));
			}
			return new ParagraphSpecification(pkwName, Id, list);
		}

		private IParagraphSpecification CreateParagraph(IParagraphDefinition paragraphDefinition, string pkwName, string Id, List<string[]> sentenceInputs)
		{
			Dictionary<string, SentenceDefinitionBase> dictionary = paragraphDefinition.Sentences.ToDictionary((ISentenceDefinition key) => key.SKWName, (ISentenceDefinition value) => (SentenceDefinitionBase)value);
			List<ISentenceSpecification> list = new List<ISentenceSpecification>();
			foreach (string[] sentenceInput in sentenceInputs)
			{
				list.Add(CreateSentences(sentenceInput[0], dictionary[sentenceInput[0]], sentenceInput.Skip(1).ToArray()));
			}
			return new ParagraphSpecification(pkwName, Id, list);
		}

		private ISentenceSpecification CreateSentences(string skwName, SentenceDefinitionBase sentenceDefinitions, string[] variables)
		{
			return new SentenceSpecification(skwName, sentenceDefinitions.Variables, variables);
		}
