	public abstract class EnumDefinitionBase
	{
		private readonly List<Tuple<string, int>> _enumerations = new List<Tuple<string, int>>();

		public EnumDefinitionBase()
		{
			SetupEnumeration();
		}

		protected abstract void SetupEnumeration();

		protected void AddEnumValue(string key, int value)
		{
			_enumerations.Add(new Tuple<string, int>(key, value));
		}

		public int GetIndexValue(string key)
		{
			return _enumerations.First((Tuple<string, int> s) => s.Item1 == key).Item2;
		}

		public int GetValue(string key)
		{
			Tuple<string, int> item = _enumerations.First((Tuple<string, int> s) => s.Item1 == key);
			return _enumerations.IndexOf(item) + 1;
		}
	}
	internal class EnumVariableDefinition<T> : VariableDefinitionBase<int> where T : EnumDefinitionBase
	{
		private readonly T _enumDefinition;

		public bool UseIndex { get; set; }

		public override int StorageSize => 1;

		public override bool IsVector => false;

		public override bool IsPair => false;

		public bool IsEnumeration => true;

		public EnumVariableDefinition()
		{
			_enumDefinition = Activator.CreateInstance<T>();
		}

		public override void ProcessDefault(ISentenceDefinition processor, IAspenProblemData problemData = null)
		{
			int defaultValue = GetDefaultValue<int>();
			processor.AddIntegerValue(defaultValue);
		}

		public override void ProcessVariable(ISentenceDefinition sentence, IVariableSpecification specification, IAspenProblemData problemData = null)
		{
			if (specification.Value is int)
			{
				int value = (int)specification.Value;
				sentence.AddIntegerValue(value);
			}
			else
			{
				int value2 = ConvertValue(specification.Value as string);
				sentence.AddIntegerValue(value2);
			}
		}

		private int ConvertSpecifications(object specification)
		{
			if (!(specification is double[] array))
			{
				if (!(specification is double value))
				{
					if (!(specification is string[] array2))
					{
						if (!(specification is string s))
						{
							if (specification is int[] array3)
							{
								return array3[0];
							}
							return (int)specification;
						}
						return StringToInteger(s);
					}
					return StringToInteger(array2[0]);
				}
				return Convert.ToInt32(value);
			}
			return Convert.ToInt32(array[0]);
		}

		protected int ConvertValue(string value)
		{
			if (!UseIndex)
			{
				return _enumDefinition.GetValue(value);
			}
			return _enumDefinition.GetIndexValue(value);
		}
	}
	public static class GensenFactories
	{
		private static volatile ILazyFactory<string, ParagraphDefinition> _primaryKeywordTableFactory;

		private static volatile ILazyFactory<string, ReactionTable> _reactionTableFactory;

		private static readonly object PrimaryKeywordTableLock = new object();

		private static readonly object ReactionTableLock = new object();

		private static readonly object ResetLock = new object();

		public static ILazyFactory<string, ParagraphDefinition> PrimaryKeyword
		{
			get
			{
				lock (PrimaryKeywordTableLock)
				{
					return _primaryKeywordTableFactory ?? (_primaryKeywordTableFactory = new PrimaryKeywordTableFactory());
				}
			}
		}

		public static ILazyFactory<string, ReactionTable> ReactionTable
		{
			get
			{
				lock (ReactionTableLock)
				{
					return _reactionTableFactory ?? (_reactionTableFactory = new ReactionTableFactory());
				}
			}
		}

		public static void ResetAll()
		{
			lock (ResetLock)
			{
				_primaryKeywordTableFactory = null;
				_reactionTableFactory = null;
			}
		}

		public static IParagraphManager CreateParagraphManager(IPlexDocument parent)
		{
			return new ParagraphManager(parent);
		}
	}
	public abstract class LazyFactory<TKey, TValue> : ILazyFactory<TKey, TValue>
	{
		protected delegate TValue Instantiater();

		private readonly Dictionary<TKey, TValue> _instancedObjects = new Dictionary<TKey, TValue>();

		private readonly object _lockingObject = new object();

		protected readonly IReadOnlyDictionary<TKey, Instantiater> Instantiaters;

		public IEnumerable<TKey> ValidKeys => Instantiaters.Keys;

		protected LazyFactory(IReadOnlyDictionary<TKey, Instantiater> instantiaters)
		{
			Instantiaters = instantiaters;
		}

		public TValue GetOrCreate(TKey key)
		{
			lock (_lockingObject)
			{
				if (_instancedObjects.TryGetValue(key, out var value))
				{
					return value;
				}
				if (!Instantiaters.ContainsKey(key))
				{
					return value;
				}
				_instancedObjects.Add(key, Instantiaters[key]());
				return _instancedObjects[key];
			}
		}

		public bool IsInstantited(TKey key)
		{
			return _instancedObjects.ContainsKey(key);
		}
	}
