	public class VariableLimitCalculatorFactory
	{
		public static IVariableLimitCalculator CreateLimitCalculator(int varLimitGroup = 0, int varLimitQual = 0, VariableLimitOpCode variableLimitOp = VariableLimitOpCode.None, int constant = 0)
		{
			switch (varLimitGroup)
			{
			case 0:
				if (varLimitQual == 0)
				{
					return new VariableLimitDefaultCalculator(constant, variableLimitOp);
				}
				return new VariableLimitCalculateByComponent(varLimitQual, constant, variableLimitOp);
			case 1:
				return new VariableLimitCalculateByLocation(varLimitQual, constant, variableLimitOp);
			case 3:
				return new VariableLimitCalculateByPhase(varLimitQual, constant, variableLimitOp);
			case 36:
				return varLimitQual switch
				{
					1 => new VariableLimitCalculateForPowerlawReaction(constant, variableLimitOp), 
					2 => new VariableLimitCalculateForLHHWReaction(constant, variableLimitOp), 
					3 => new VariableLimitCalculateForUserCrystalReaction(constant, variableLimitOp), 
					4 => new VariableLimitCalculateForLHHWReaction(constant, variableLimitOp), 
					5 => new VariableLimitCalculateForChemistryStoicGen(constant, variableLimitOp), 
					6 => new VariableLimitCalculateForChemistrySaltDissGen(constant, variableLimitOp), 
					7 => new VariableLimitCalculateForChemistryKStoicKSaltGen(constant, variableLimitOp), 
					8 => new VariableLimitCalculateForChemistrySaltRetnGen(constant, variableLimitOp), 
					_ => new VariableLimitCalculateForUserCrystalReaction(constant, variableLimitOp), 
				};
			default:
				return new VariableLimitDefaultCalculator(constant, variableLimitOp);
			}
		}
	}
