	public class IntegerScalarVariableDefinition : VariableDefinitionBase<int>
	{
		public override bool IsVector => false;

		public override bool IsPair => false;

		public override int StorageSize => 1;

		public IntegerScalarVariableDefinition()
		{
			base.DefaultValue = 0;
			base.UpperLimit = int.MaxValue;
			base.LowerLimit = int.MinValue;
		}

		public override void ProcessDefault(ISentenceDefinition processor, IAspenProblemData problemData = null)
		{
			int defaultValue = GetDefaultValue<int>();
			processor.AddIntegerValue(defaultValue);
		}

		public override void ProcessVariable(ISentenceDefinition processor, IVariableSpecification specification, IAspenProblemData problemData = null)
		{
			int value = ConvertSpecifications(specification.Value);
			processor.AddIntegerValue(value);
		}

		private int ConvertSpecifications(object specification)
		{
			if (!(specification is double[] array))
			{
				if (!(specification is double value))
				{
					if (!(specification is string[] array2))
					{
						if (!(specification is string s))
						{
							if (specification is int[] array3)
							{
								return array3[0];
							}
							return (int)specification;
						}
						return StringToInteger(s);
					}
					return StringToInteger(array2[0]);
				}
				return Convert.ToInt32(value);
			}
			return Convert.ToInt32(array[0]);
		}
	}
	public class IntegerVectorVariableDefinition : VariableDefinitionBase<int>
	{
		public override bool IsVector => true;

		public override bool IsPair => false;

		public override int StorageSize => 2;

		public IntegerVectorVariableDefinition()
		{
			base.DefaultValue = 0;
			base.UpperLimit = int.MaxValue;
			base.LowerLimit = int.MinValue;
		}

		public override void ProcessDefault(ISentenceDefinition processor, IAspenProblemData problemData = null)
		{
			if (base.VariableLimitCalculator != null && base.VariableLimitCalculator.OpCode == VariableLimitOpCode.AlwaysAllocateVectorInBead)
			{
				int num = ComputeLimit(problemData);
				int defaultValue = GetDefaultValue<int>();
				processor.AddIntegerVector(Array.ConvertAll(new int[num], (int initArrayValue) => defaultValue));
			}
			else
			{
				processor.AddIntegerVector(new int[0]);
			}
		}

		public override void ProcessVariable(ISentenceDefinition processor, IVariableSpecification specification, IAspenProblemData problemData = null)
		{
			if (base.VariableLimitCalculator != null && base.VariableLimitCalculator.OpCode == VariableLimitOpCode.AlwaysAllocateVectorInBead)
			{
				int num = ComputeLimit(problemData);
				int defaultValue = GetDefaultValue<int>();
				int[] initArray = Array.ConvertAll(new int[num], (int initArrayValue) => defaultValue);
				int[] values = ConvertSpecifications(specification.Value, initArray);
				processor.AddIntegerVector(values);
			}
			else
			{
				int[] values2 = ConvertSpecifications(specification.Value);
				processor.AddIntegerVector(values2);
			}
		}

		private int[] ConvertSpecifications(object specification, int[] initArray = null)
		{
			int[] values = new int[0];
			if (initArray != null)
			{
				values = initArray;
			}
			try
			{
				double[] array = specification as double[];
				if (array == null)
				{
					if (!(specification is double value))
					{
						string[] array2 = specification as string[];
						if (array2 == null)
						{
							if (!(specification is string s))
							{
								if (!(specification is int num))
								{
									int[] array3 = specification as int[];
									if (array3 != null)
									{
										if (values.Length == 0)
										{
											values = new int[array3.Length];
										}
										Enumerable.Range(0, array3.Length).ToList().ForEach(delegate(int i)
										{
											values[i] = Convert.ToInt32(array3[i]);
										});
									}
									else
									{
										values = (int[])specification;
									}
								}
								else
								{
									values = new int[1];
									values[0] = num;
								}
							}
							else
							{
								values = new int[1];
								values[0] = StringToInteger(s);
							}
						}
						else
						{
							if (values.Length == 0)
							{
								values = new int[array2.Length];
							}
							Enumerable.Range(0, array2.Length).ToList().ForEach(delegate(int i)
							{
								values[i] = StringToInteger(array2[i]);
							});
						}
					}
					else
					{
						values = new int[1];
						values[0] = Convert.ToInt32(value);
					}
				}
				else
				{
					if (values.Length == 0)
					{
						values = new int[array.Length];
					}
					Enumerable.Range(0, array.Length).ToList().ForEach(delegate(int i)
					{
						values[i] = Convert.ToInt32(array[i]);
					});
				}
			}
			catch
			{
				throw new ArgumentException(base.TKWName.ToString() + " is overspecified. The limit is " + initArray.Length + ".");
			}
			return values;
		}
	}
