	internal class ObservableList<T> : IObservableListExt<T>, IObservableList<T>, IList<T>, ICollection<T>, IEnumerable<T>, IEnumerable, INotifyCollectionChanged
	{
		protected List<T> _list = new List<T>();

		private ILazyFactory<string, T> _factory;

		public bool AllowDuplicates { get; private set; }

		public T this[int index]
		{
			get
			{
				return _list[index];
			}
			set
			{
				CheckIndex(index);
				if ((_list[index] != null || value != null) && !_list[index].Equals(value) && (AllowDuplicates || !Contains(value)))
				{
					T val = _list[index];
					_list[index] = value;
					OnCollectionChanged(new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Replace, value, val));
				}
			}
		}

		public int Count => _list.Count();

		public bool IsReadOnly => false;

		public event NotifyCollectionChangedEventHandler CollectionChanged;

		public ObservableList()
			: this((IEnumerable<T>)null, (ILazyFactory<string, T>)null, allowDuplicates: true)
		{
		}

		public ObservableList(bool allowDuplicates)
			: this((IEnumerable<T>)null, (ILazyFactory<string, T>)null, allowDuplicates)
		{
		}

		public ObservableList(IEnumerable<T> list)
			: this(list, (ILazyFactory<string, T>)null, allowDuplicates: true)
		{
		}

		public ObservableList(IEnumerable<T> list, bool allowDuplicates)
			: this(list, (ILazyFactory<string, T>)null, allowDuplicates)
		{
		}

		public ObservableList(ILazyFactory<string, T> objectFactory)
			: this((IEnumerable<T>)null, objectFactory, allowDuplicates: true)
		{
		}

		public ObservableList(ILazyFactory<string, T> objectFactory, bool allowDuplicates)
			: this((IEnumerable<T>)null, objectFactory, allowDuplicates)
		{
		}

		public ObservableList(IEnumerable<T> list, ILazyFactory<string, T> objectFactory)
			: this(list, objectFactory, allowDuplicates: true)
		{
		}

		public ObservableList(IEnumerable<T> list, ILazyFactory<string, T> objectFactory, bool allowDuplicates)
		{
			if (list != null)
			{
				_list = new List<T>(list);
			}
			_factory = objectFactory;
			AllowDuplicates = allowDuplicates;
		}

		private void CheckIndex(int index)
		{
			if (index < 0 || Count <= index)
			{
				throw new IndexOutOfRangeException($"The specified index ({index}) is out of range " + $"(where Count = {Count}).");
			}
		}

		private void OnCollectionChanged(NotifyCollectionChangedEventArgs args)
		{
			this.CollectionChanged?.Invoke(this, args);
		}

		public void Add(T item)
		{
			if (AllowDuplicates || !Contains(item))
			{
				_list.Add(item);
				OnCollectionChanged(new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Add, item));
			}
		}

		public T AddByName(string name)
		{
			T factoryItem = GetFactoryItem(name);
			Add(factoryItem);
			return factoryItem;
		}

		private T GetFactoryItem(string name)
		{
			if (_factory == null)
			{
				throw new ArgumentException("This object does not include a factory to add by name.");
			}
			try
			{
				return _factory.GetOrCreate(name);
			}
			catch (Exception)
			{
				throw new ArgumentException("Bad name " + name.ToUpper() + ".");
			}
		}

		public void AddRange(IEnumerable<T> items)
		{
			List<T> list = new List<T>();
			if (AllowDuplicates)
			{
				list.AddRange(items);
			}
			else
			{
				foreach (T item in items)
				{
					if (!Contains(item) && !list.Contains(item))
					{
						list.Add(item);
					}
				}
			}
			if (list.Count != 0)
			{
				_list.AddRange(list);
				OnCollectionChanged(new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Add, items));
			}
		}

		public void AddByName(IEnumerable<string> items)
		{
			List<T> list = new List<T>();
			if (AllowDuplicates)
			{
				foreach (string item in items)
				{
					T factoryItem = GetFactoryItem(item);
					list.Add(factoryItem);
				}
			}
			else
			{
				foreach (string item2 in items)
				{
					T factoryItem2 = GetFactoryItem(item2);
					if (!Contains(factoryItem2))
					{
						list.Add(factoryItem2);
					}
				}
			}
			if (list.Count != 0)
			{
				AddRange(list);
			}
		}

		public void Clear()
		{
			_list.Clear();
			OnCollectionChanged(new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Reset));
		}

		public bool Contains(T item)
		{
			return _list.Contains(item);
		}

		public void CopyTo(T[] array, int arrayIndex)
		{
			_list.CopyTo(array, arrayIndex);
		}

		public int IndexOf(T item)
		{
			return _list.IndexOf(item);
		}

		public void Insert(int index, T item)
		{
			CheckIndex(index);
			_list.Insert(index, item);
			OnCollectionChanged(new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Add, item, index));
		}

		public bool Remove(T item)
		{
			if (_list.Remove(item))
			{
				OnCollectionChanged(new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Remove, item));
				return true;
			}
			return false;
		}

		public void RemoveAt(int index)
		{
			CheckIndex(index);
			T val = _list[index];
			_list.RemoveAt(index);
			OnCollectionChanged(new NotifyCollectionChangedEventArgs(NotifyCollectionChangedAction.Remove, val, index));
		}

		public IEnumerator<T> GetEnumerator()
		{
			return _list.GetEnumerator();
		}

		IEnumerator IEnumerable.GetEnumerator()
		{
			return GetEnumerator();
		}
	}
	public abstract class ParagraphDefinition : IParagraphDefinition
	{
		public int ReqIDs;

		public int OptionIDs;

		public int CallIfMissing;

		public int WhenToCall;

		public int SKWCode;

		public int SemanticRoutineNumber;

		public int NumberOfSKWs;

		public bool AllowForSimulation;

		public bool AllowForCosting;

		public bool AllowForDataRegression;

		public bool AllowForTableGeneration;

		public bool AllowForEstimation;

		public bool AllowForAssayAnalysis;

		public bool AllowForStandaloneProperties;

		public string PKWName { get; set; }

		public string AlternatePKWName { get; set; }

		public string PKWAbbreviationName { get; set; }

		public int SortCode { get; set; }

		public IList<ISentenceDefinition> Sentences { get; internal set; }

		public string ParagraphId { get; set; }

		public List<string[]> InputSpecifications { get; set; }

		public ParagraphDefinition()
		{
		}

		public void Report(StreamWriter writer)
		{
		}

		public IDictionary<string, int> GetLocations()
		{
			Dictionary<string, int> locations = new Dictionary<string, int>();
			int intOffset = 1;
			int realOffset = -1;
			Sentences.ToList().ForEach(delegate(ISentenceDefinition s)
			{
				s.GetLocations(locations, ref intOffset, ref realOffset);
			});
			return locations;
		}

		public string[] GetIntegerReport()
		{
			int num = Sentences.Sum((ISentenceDefinition s) => s.GetFixedIntegerLength());
			int num2 = Sentences.Sum((ISentenceDefinition s) => s.GetVariableIntegerLength());
			string[] array = new string[num + num2];
			int num3 = 0;
			int key = num;
			IDictionary<int, int[]> longStringBeadDictionary = GetLongStringBeadDictionary();
			foreach (ISentenceDefinition sentence in Sentences)
			{
				string text = ";COUNTED";
				if (!sentence.ProcessSentenceInGensen())
				{
					text = ";UNCOUNTED";
				}
				string definitionName = sentence.GetDefinitionName();
				string[] integerVariableNames = sentence.GetIntegerVariableNames();
				int[] fixedIntegerArray = sentence.GetFixedIntegerArray();
				int num4 = 0;
				int[] array2 = fixedIntegerArray;
				for (int num5 = 0; num5 < array2.Length; num5++)
				{
					int num6 = array2[num5];
					if (num4 == integerVariableNames.Length)
					{
						array[num3++] = definitionName + ";SentenceCount;" + num6 + text;
						continue;
					}
					if (num4 > integerVariableNames.Length)
					{
						array[num3++] = definitionName + ";UNK;" + num6 + text;
						continue;
					}
					array[num3++] = definitionName + ";" + integerVariableNames[num4++] + ";" + num6 + text;
				}
				array2 = sentence.GetVariableIntegerArray();
				for (int num5 = 0; num5 < array2.Length; num5++)
				{
					int num7 = array2[num5];
					if (longStringBeadDictionary.ContainsKey(key))
					{
						array[key++] = definitionName + ";VAR;" + (num7 + 800000000) + text;
					}
					else
					{
						array[key++] = definitionName + ";VAR;" + num7 + text;
					}
				}
			}
			return array;
		}

		public string[] GetRealReport()
		{
			int num = Sentences.Sum((ISentenceDefinition s) => s.GetFixedRealLength());
			int num2 = Sentences.Sum((ISentenceDefinition s) => s.GetVariableRealLength());
			string[] array = new string[num + num2];
			int num3 = 0;
			int num4 = num;
			foreach (ISentenceDefinition sentence in Sentences)
			{
				string text = ";COUNTED";
				if (!sentence.ProcessSentenceInGensen())
				{
					text = ";UNCOUNTED";
				}
				string definitionName = sentence.GetDefinitionName();
				string[] realVariableNames = sentence.GetRealVariableNames();
				double[] fixedRealArray = sentence.GetFixedRealArray();
				int num5 = 0;
				double[] array2 = fixedRealArray;
				foreach (double num7 in array2)
				{
					array[num3++] = definitionName + ";" + realVariableNames[num5] + ";" + num7 + text;
					if (num5 < realVariableNames.Length - 1)
					{
						num5++;
					}
				}
				array2 = sentence.GetVariableRealArray();
				foreach (double num8 in array2)
				{
					array[num4++] = definitionName + ";" + realVariableNames[num5] + ";" + num8 + text;
					if (num5 < realVariableNames.Length - 1)
					{
						num5++;
					}
				}
			}
			return array;
		}

		public int[] GetIntegerArray()
		{
			int num = Sentences.Sum((ISentenceDefinition s) => s.GetFixedIntegerLength());
			int num2 = Sentences.Sum((ISentenceDefinition s) => s.GetVariableIntegerLength());
			int[] results = new int[num + num2];
			int i = 0;
			int j = num;
			foreach (ISentenceDefinition sentence in Sentences)
			{
				if (sentence.ProcessSentenceInGensen())
				{
					sentence.GetFixedIntegerArray().ToList().ForEach(delegate(int s)
					{
						results[i++] = s;
					});
					sentence.GetVariableIntegerArray().ToList().ForEach(delegate(int s)
					{
						results[j++] = s;
					});
				}
			}
			foreach (KeyValuePair<int, int[]> item in GetLongStringBeadDictionary())
			{
				results[item.Key] += 800000000;
			}
			return results;
		}

		public IDictionary<int, int[]> GetLongStringBeadDictionary()
		{
			Dictionary<int, int[]> dictionary = new Dictionary<int, int[]>();
			foreach (ISentenceDefinition sentence in Sentences)
			{
				Dictionary<int, int[]> longStringBeadDictionary = sentence.GetLongStringBeadDictionary();
				if (longStringBeadDictionary == null)
				{
					continue;
				}
				foreach (KeyValuePair<int, int[]> item in longStringBeadDictionary)
				{
					dictionary.Add(item.Key - 1, item.Value);
				}
			}
			return dictionary;
		}

		public int GetIntegerLength()
		{
			int num = Sentences.Sum((ISentenceDefinition s) => s.GetFixedIntegerLength());
			int num2 = Sentences.Sum((ISentenceDefinition s) => s.GetVariableIntegerLength());
			return num + num2;
		}

		public int GetSentenceCount(string sentenceName)
		{
			if (Sentences == null)
			{
				return 0;
			}
			foreach (ISentenceDefinition sentence in Sentences)
			{
				string definitionName = sentence.GetDefinitionName();
				if (!(sentenceName != definitionName))
				{
					string[] integerVariableNames = sentence.GetIntegerVariableNames();
					int[] fixedIntegerArray = sentence.GetFixedIntegerArray();
					if (fixedIntegerArray.Length != 0)
					{
						return fixedIntegerArray[integerVariableNames.Length];
					}
				}
			}
			return 0;
		}

		public double[] GetRealArray()
		{
			int num = Sentences.Sum((ISentenceDefinition s) => s.GetFixedRealLength());
			int num2 = Sentences.Sum((ISentenceDefinition s) => s.GetVariableRealLength());
			double[] results = new double[num + num2];
			int i = 0;
			int j = num;
			foreach (ISentenceDefinition sentence in Sentences)
			{
				sentence.GetFixedRealArray().ToList().ForEach(delegate(double s)
				{
					results[i++] = s;
				});
				sentence.GetVariableRealArray().ToList().ForEach(delegate(double s)
				{
					results[j++] = s;
				});
			}
			return results;
		}

		public int GetRealLength()
		{
			int num = Sentences.Sum((ISentenceDefinition s) => s.GetFixedRealLength());
			int num2 = Sentences.Sum((ISentenceDefinition s) => s.GetVariableRealLength());
			return num + num2;
		}

		public void ProcessParagraph(IParagraphSpecification specification)
		{
			int num = Sentences.Sum((ISentenceDefinition s) => s.GetFixedIntegerLength()) + 1;
			int num2 = Sentences.Sum((ISentenceDefinition s) => s.GetFixedRealLength()) + 1;
			foreach (ISentenceDefinition sentenceDefinition in Sentences)
			{
				GetIntegerArray();
				IEnumerable<ISentenceSpecification> source = specification.Sentences.Where((ISentenceSpecification s) => MatchSentenceName(s.Name, sentenceDefinition));
				if (source.Any())
				{
					sentenceDefinition.ProcessSentence(source.ToList(), num, num2);
					num += sentenceDefinition.GetVariableIntegerLength();
					num2 += sentenceDefinition.GetVariableRealLength();
				}
				else
				{
					sentenceDefinition.DefaultSentence(num, num2);
					num += sentenceDefinition.GetVariableIntegerLength();
					num2 += sentenceDefinition.GetVariableRealLength();
				}
			}
		}

		public void ProcessParagraph(IParagraphSpecification specification, IAspenProblemData gensenPreprocessedData)
		{
			int num = Sentences.Sum((ISentenceDefinition s) => s.GetFixedIntegerLength()) + 1;
			int num2 = Sentences.Sum((ISentenceDefinition s) => s.GetFixedRealLength()) + 1;
			foreach (ISentenceDefinition sentenceDefinition in Sentences)
			{
				gensenPreprocessedData.GensenInformation.CurrentGensenIntArray = GetIntegerArray();
				IEnumerable<ISentenceSpecification> source = specification.Sentences.Where((ISentenceSpecification s) => MatchSentenceName(s.Name, sentenceDefinition));
				if (source.Any())
				{
					sentenceDefinition.ProcessSentence(source.ToList(), num, num2, gensenPreprocessedData);
					num += sentenceDefinition.GetVariableIntegerLength();
					num2 += sentenceDefinition.GetVariableRealLength();
				}
				else
				{
					sentenceDefinition.DefaultSentence(num, num2, gensenPreprocessedData);
					num += sentenceDefinition.GetVariableIntegerLength();
					num2 += sentenceDefinition.GetVariableRealLength();
				}
			}
		}

		private bool MatchSentenceName(string name, ISentenceDefinition sentence)
		{
			if (!(sentence.SKWName == name) && !(sentence.AlternateSKWName == name))
			{
				return sentence.SKWAbbreviationName == name;
			}
			return true;
		}
	}
