	public class RealScalarVariableDefinition : VariableDefinitionBase<double>
	{
		public override bool IsVector => false;

		public override bool IsPair => false;

		public override int StorageSize => 1;

		public override bool StoreAsDouble => true;

		public RealScalarVariableDefinition()
		{
			base.DefaultValue = 0.0;
			base.UpperLimit = double.MaxValue;
			base.LowerLimit = double.MinValue;
		}

		public override void ProcessVariable(ISentenceDefinition processor, IVariableSpecification specification, IAspenProblemData problemData = null)
		{
			double value = ConvertSpecifications(specification.Value);
			processor.AddRealValue(value);
		}

		public override void ProcessDefault(ISentenceDefinition processor, IAspenProblemData problemData = null)
		{
			double defaultValue = GetDefaultValue<double>();
			processor.AddRealValue(defaultValue);
		}

		private double ConvertSpecifications(object specification)
		{
			if (!(specification is double result))
			{
				if (!(specification is string s))
				{
					if (specification is int num)
					{
						return num;
					}
					return (double)specification;
				}
				return StringToDouble(s);
			}
			return result;
		}
	}
	public class RealVectorVariableDefinition : VariableDefinitionBase<double>
	{
		public override bool IsVector => true;

		public override bool IsPair => false;

		public override int StorageSize => 2;

		public override bool StoreAsDouble => true;

		public RealVectorVariableDefinition()
		{
			base.DefaultValue = 0.0;
			base.UpperLimit = double.MaxValue;
			base.LowerLimit = double.MinValue;
		}

		public override void ProcessDefault(ISentenceDefinition processor, IAspenProblemData problemData = null)
		{
			if (base.VariableLimitCalculator != null && base.VariableLimitCalculator.OpCode == VariableLimitOpCode.AlwaysAllocateVectorInBead)
			{
				int num = ComputeLimit(problemData);
				double defaultValue = GetDefaultValue<double>();
				processor.AddRealVector(Array.ConvertAll(new double[num], (double initArrayValue) => defaultValue));
			}
			else
			{
				processor.AddRealVector(new double[0]);
			}
		}

		public override void ProcessVariable(ISentenceDefinition processor, IVariableSpecification specification, IAspenProblemData problemData = null)
		{
			if (base.VariableLimitCalculator != null && base.VariableLimitCalculator.OpCode == VariableLimitOpCode.AlwaysAllocateVectorInBead)
			{
				int num = ComputeLimit(problemData);
				double defaultValue = GetDefaultValue<double>();
				double[] initArray = Array.ConvertAll(new double[num], (double initArrayValue) => defaultValue);
				double[] values = ConvertSpecifications(specification.Value, initArray);
				processor.AddRealVector(values);
			}
			else
			{
				double[] values2 = ConvertSpecifications(specification.Value);
				processor.AddRealVector(values2);
			}
		}

		private double[] ConvertSpecifications(object specification, double[] initArray = null)
		{
			double[] values = new double[0];
			if (initArray != null)
			{
				values = initArray;
			}
			try
			{
				if (!(specification is double num))
				{
					string[] array = specification as string[];
					if (array == null)
					{
						if (!(specification is string s))
						{
							int[] array2 = specification as int[];
							if (array2 == null)
							{
								if (!(specification is int num2))
								{
									double[] array3 = specification as double[];
									if (array3 != null)
									{
										if (values.Length == 0)
										{
											values = new double[array3.Length];
										}
										Enumerable.Range(0, array3.Length).ToList().ForEach(delegate(int i)
										{
											values[i] = Convert.ToDouble(array3[i]);
										});
									}
									else
									{
										values = (double[])specification;
									}
								}
								else
								{
									values = new double[1];
									values[0] = num2;
								}
							}
							else
							{
								if (values.Length == 0)
								{
									values = new double[array2.Length];
								}
								Enumerable.Range(0, array2.Length).ToList().ForEach(delegate(int i)
								{
									values[i] = Convert.ToDouble(array2[i]);
								});
							}
						}
						else
						{
							values = new double[1];
							values[0] = StringToDouble(s);
						}
					}
					else
					{
						if (values.Length == 0)
						{
							values = new double[array.Length];
						}
						Enumerable.Range(0, array.Length).ToList().ForEach(delegate(int i)
						{
							values[i] = StringToDouble(array[i]);
						});
					}
				}
				else
				{
					values = new double[1];
					values[0] = num;
				}
			}
			catch
			{
				throw new ArgumentException(base.TKWName.ToString() + " is overspecified. The limit is " + initArray.Length + ".");
			}
			return values;
		}
	}
