						new LongStringVectorVariableDefinition
						{
							TKWName = "Description",
							AlternateTKWName = "LongString",
							TKWAbbreviationName = "Desc"
						}
					}
				}
			};
		}
	}
	public abstract class SentenceDefinitionBase : ISentenceDefinition
	{
		private int _longStringOffSet;

		protected readonly IList<int> _fixedIntegerArray = new List<int>();

		protected readonly IList<int> _variableIntegerArray = new List<int>();

		protected readonly IList<double> _fixedRealArray = new List<double>();

		protected readonly IList<double> _variableRealArray = new List<double>();

		protected bool _storeIndex;

		protected int _numberOfSentences;

		protected readonly IList<int> _integerVectors = new List<int>();

		protected readonly IList<double> _realVectors = new List<double>();

		protected readonly Dictionary<int, int[]> _stringBeadDictionary = new Dictionary<int, int[]>();

		protected int _integerOffset;

		protected int _realOffset;

		public string SKWName { get; set; }

		public string AlternateSKWName { get; set; }

		public string SKWAbbreviationName { get; set; }

		public abstract string Structure { get; }

		public int NumberIdCode { get; set; }

		public int JustifyContentFlag { get; set; }

		public int TKWFlag { get; set; }

		public int CountTKWs { get; set; }

		public int NumberOfTkws { get; set; }

		public IList<IVariableDefinition> Variables { get; set; }

		public virtual bool ProcessSentenceInGensen()
		{
			if (CountTKWs == 0)
			{
				return true;
			}
			if (CountTKWs == 1)
			{
				return false;
			}
			return true;
		}

		public virtual int GetFixedIntegerLength()
		{
			if (CountTKWs == 1)
			{
				return 0;
			}
			return Variables.Count() + 1;
		}

		public virtual int GetFixedRealLength()
		{
			_ = CountTKWs;
			_ = 1;
			return 0;
		}

		public void Report(StreamWriter writer)
		{
			writer.WriteLine("Sentence \"{0}\" Alternate: \"{1}\", Short: \"{2}\"", SKWName, AlternateSKWName, SKWAbbreviationName);
			writer.WriteLine("         Sentence Type: {0}", Structure);
			writer.WriteLine("         Number Of Variables: {0}", Variables.Count);
			Variables.ToList().ForEach(delegate(IVariableDefinition v)
			{
				v.Report(writer);
			});
		}

		public virtual void GetLocations(IDictionary<string, int> locations, ref int intOffset, ref int realOffset)
		{
			if (CountTKWs == 1)
			{
				_ = SKWName;
				return;
			}
			int offset = intOffset;
			Variables.ToList().ForEach(delegate(IVariableDefinition v)
			{
				locations.Add(GenerateLocationKey(v), offset++);
			});
			intOffset = offset + 1;
		}

		protected string GenerateLocationKey(IVariableDefinition variable)
		{
			return SKWName + "." + variable.TKWName;
		}

		public Dictionary<int, int[]> GetLongStringBeadDictionary()
		{
			return _stringBeadDictionary;
		}

		public int GetVariableIntegerLength()
		{
			return _variableIntegerArray.Count;
		}

		public int GetVariableRealLength()
		{
			return _variableRealArray.Count;
		}

		public string GetDefinitionName()
		{
			return SKWName;
		}

		public string[] GetIntegerVariableNames()
		{
			List<string> list = new List<string>();
			foreach (IVariableDefinition variable in Variables)
			{
				if (!(GetType() != typeof(SimpleSentenceDefinition)) && variable.DataType1 == 2)
				{
					continue;
				}
				if (GetType() == typeof(SimpleSentenceDefinition) && variable.StorageSize >= 2)
				{
					for (int i = 0; i < variable.StorageSize; i++)
					{
						list.Add(variable.TKWName);
					}
				}
				else
				{
					list.Add(variable.TKWName);
				}
			}
			return list.ToArray();
		}

		public string[] GetRealVariableNames()
		{
			List<string> list = new List<string>();
			foreach (IVariableDefinition variable in Variables)
			{
				if (variable.DataType1 == 2)
				{
					list.Add(variable.TKWName);
				}
				else if (variable.StoreAsDouble)
				{
					list.Add(variable.TKWName);
				}
			}
			return list.ToArray();
		}

		public int[] GetFixedIntegerArray()
		{
			if (ProcessSentenceInGensen())
			{
				return _fixedIntegerArray.ToArray();
			}
			return new int[0];
		}

		public double[] GetFixedRealArray()
		{
			if (ProcessSentenceInGensen())
			{
				return _fixedRealArray.ToArray();
			}
			return new double[0];
		}

		public int[] GetVariableIntegerArray()
		{
			if (ProcessSentenceInGensen())
			{
				return _variableIntegerArray.ToArray();
			}
			return new int[0];
		}

		public double[] GetVariableRealArray()
		{
			if (ProcessSentenceInGensen())
			{
				return _variableRealArray.ToArray();
			}
			return new double[0];
		}

		public abstract void DefaultSentence(int integerOffset, int realOffset);

		public abstract void ProcessSentence(IList<ISentenceSpecification> sentences, int integerOffset, int realOffset);

		public abstract void DefaultSentence(int integerOffset, int realOffset, IAspenProblemData caseData);

		public abstract void ProcessSentence(IList<ISentenceSpecification> sentences, int integerOffset, int realOffset, IAspenProblemData caseData);

		protected virtual void StoreSystemDimension(int systemDimension)
		{
			_fixedIntegerArray.Add(systemDimension);
		}

		public virtual void AddIntegerValue(int value)
		{
			if (_storeIndex)
			{
				_fixedIntegerArray.Add(_integerOffset);
				_integerOffset += _numberOfSentences;
				_storeIndex = false;
			}
			_variableIntegerArray.Add(value);
		}

		public virtual void AddIntegerVector(int[] values)
		{
			if (_storeIndex)
			{
				_fixedIntegerArray.Add(_integerOffset);
				_integerOffset += 2 * _numberOfSentences;
				_storeIndex = false;
			}
			if (values.Any())
			{
				_variableIntegerArray.Add(values.Count());
				_variableIntegerArray.Add(_integerOffset);
			}
			else
			{
				_variableIntegerArray.Add(0);
				_variableIntegerArray.Add(0);
			}
			values.ToList().ForEach(delegate(int i)
			{
				_integerVectors.Add(i);
			});
			_integerOffset += values.Count();
		}

		public virtual void AddLongStringValue(string value, IAspenProblemData problemData = null)
		{
			if (_storeIndex)
			{
				_longStringOffSet = _integerOffset;
				_fixedIntegerArray.Add(_integerOffset);
				_integerOffset += _numberOfSentences;
				_storeIndex = false;
			}
			if (value.Length > 0)
			{
				if (value == "MISSING")
				{
					_variableIntegerArray.Add(99999999);
				}
				else
				{
					_variableIntegerArray.Add(100000123);
					_stringBeadDictionary.Add(_longStringOffSet, value.Holleriths());
				}
			}
			else
			{
				_variableIntegerArray.Add(0);
			}
			_longStringOffSet++;
		}

		public virtual void AddLongStringVector(string[] values, IAspenProblemData problemData = null)
		{
			int startBead = 100000120;
			if (_storeIndex)
			{
				_fixedIntegerArray.Add(_integerOffset);
				_integerOffset += 2 * _numberOfSentences;
				_storeIndex = false;
			}
			if (values.Any())
			{
				_variableIntegerArray.Add(values.Count());
				_variableIntegerArray.Add(_integerOffset);
				_longStringOffSet = _integerOffset;
			}
			else
			{
				_variableIntegerArray.Add(0);
				_variableIntegerArray.Add(0);
			}
			values.ToList().ForEach(delegate
			{
				_integerVectors.Add(startBead++);
			});
			for (int num = 0; num < values.Count(); num++)
			{
				_stringBeadDictionary.Add(_longStringOffSet + num, values[num].Holleriths());
			}
		}

		public virtual void AddRealValue(double value)
		{
			if (_storeIndex)
			{
				_fixedIntegerArray.Add(_realOffset);
				_realOffset += _numberOfSentences;
				_storeIndex = false;
			}
			_variableRealArray.Add(value);
		}

		public virtual void AddRealVector(double[] values)
		{
			if (_storeIndex)
			{
				_fixedIntegerArray.Add(_integerOffset);
				_integerOffset += 2 * _numberOfSentences;
				_storeIndex = false;
			}
			if (values.Any())
			{
				_variableIntegerArray.Add(values.Count());
				_variableIntegerArray.Add(_realOffset);
			}
			else
			{
				_variableIntegerArray.Add(0);
				_variableIntegerArray.Add(0);
			}
			values.ToList().ForEach(delegate(double i)
			{
				_realVectors.Add(i);
			});
			_realOffset += values.Count();
		}

		public virtual void AddShortStringValue(string value)
		{
			if (_storeIndex)
			{
				_fixedIntegerArray.Add(_integerOffset);
				_integerOffset += 2 * _numberOfSentences;
				_storeIndex = false;
			}
			int[] array = value.Holleriths(2);
			_variableIntegerArray.Add(array[0]);
			_variableIntegerArray.Add(array[1]);
		}

		public virtual void AddShortStringVector(string[] values)
		{
			if (_storeIndex)
			{
				_fixedIntegerArray.Add(_integerOffset);
				_integerOffset += 2 * _numberOfSentences;
				_storeIndex = false;
			}
			if (values.Any())
			{
				_variableIntegerArray.Add(values.Count());
				_variableIntegerArray.Add(_integerOffset);
			}
			else
			{
				_variableIntegerArray.Add(0);
				_variableIntegerArray.Add(0);
			}
			for (int i = 0; i < values.Length; i++)
			{
				int[] array = values[i].Holleriths(2);
				_integerVectors.Add(array[0]);
				_integerVectors.Add(array[1]);
			}
			_integerOffset += 2 * values.Count();
		}

		protected void ProcessVariableDefault(IVariableDefinition variableDefinition, IAspenProblemData aspenProblemData = null)
		{
			variableDefinition.ProcessDefault(this, aspenProblemData);
		}

		protected void ProcessVariableSpecification(IVariableDefinition variableDefinition, IVariableSpecification variableSpecification)
		{
			variableDefinition.ProcessVariable(this, variableSpecification);
		}

		protected bool MatchVariableNames(IVariableDefinition definition, string name)
		{
			if (!(definition.TKWName == name) && !(definition.AlternateTKWName == name))
			{
				return definition.TKWAbbreviationName == name;
			}
			return true;
		}

		protected void StoreVectors()
		{
			_integerVectors.ToList().ForEach(delegate(int s)
			{
				_variableIntegerArray.Add(s);
			});
			_integerVectors.Clear();
			_realVectors.ToList().ForEach(delegate(double s)
			{
				_variableRealArray.Add(s);
			});
			_realVectors.Clear();
		}

		protected IVariableSpecification FindVariableSpecification(string name, ISentenceDefinition sentence, IList<IVariableSpecification> specs)
		{
			IVariableDefinition definition = sentence.Variables.First((IVariableDefinition v) => MatchVariableNames(v, name));
			return specs.FirstOrDefault((IVariableSpecification v) => MatchVariableNames(definition, v.Name));
		}

		protected int[] FindIndexValues(IList<ISentenceSpecification> sentences, int index)
		{
			IVariableDefinition idVariable = Variables[index];
			return (from g in sentences.SelectMany((ISentenceSpecification s) => s.Variables.Where((IVariableSpecification v) => MatchVariableNames(idVariable, v.Name)))
				group g by g.Value into s
				select Convert.ToInt32(s.Key)).ToArray();
		}

		protected void StoreIndexValues(int[] indicies)
		{
			_fixedIntegerArray.Add(_integerOffset);
			foreach (int item in indicies)
			{
				_variableIntegerArray.Add(item);
			}
			_integerOffset += indicies.Length;
			StoreVectors();
		}

		protected ISentenceSpecification GetSentenceForOneIndex(IList<ISentenceSpecification> sentences, int index)
		{
			IVariableDefinition idVariable = Variables[0];
			ISentenceSpecification sentenceSpecification = null;
			foreach (ISentenceSpecification sentence in sentences)
			{
				if (Convert.ToInt32(sentence.Variables.First((IVariableSpecification v) => MatchVariableNames(idVariable, v.Name)).Value) != index)
				{
					continue;
				}
				if (sentenceSpecification == null)
				{
					sentenceSpecification = sentence;
					continue;
				}
				foreach (IVariableSpecification variable in sentence.Variables)
				{
					if (!MatchVariableNames(idVariable, variable.Name))
					{
						IVariableSpecification variableSpecification = FindVariableSpecification(variable.Name, this, sentenceSpecification.Variables);
						if (variableSpecification != null)
						{
							sentenceSpecification.Variables.Remove(variableSpecification);
						}
						sentenceSpecification.Variables.Add(variable);
					}
				}
			}
			return sentenceSpecification;
		}

		protected ISentenceSpecification GetSentenceForTwoIndices(IList<ISentenceSpecification> sentences, int index1, int index2)
		{
			IVariableDefinition id1Variable = Variables[0];
			IVariableDefinition id2Variable = Variables[1];
			ISentenceSpecification sentenceSpecification = null;
			foreach (ISentenceSpecification sentence in sentences)
			{
				IVariableSpecification variableSpecification = sentence.Variables.First((IVariableSpecification v) => MatchVariableNames(id1Variable, v.Name));
				IVariableSpecification variableSpecification2 = sentence.Variables.First((IVariableSpecification v) => MatchVariableNames(id2Variable, v.Name));
				if (Convert.ToInt32(variableSpecification.Value) != index1 || Convert.ToInt32(variableSpecification2.Value) != index2)
				{
					continue;
				}
				if (sentenceSpecification == null)
				{
					sentenceSpecification = sentence;
					continue;
				}
				foreach (IVariableSpecification variable in sentence.Variables)
				{
					if (!MatchVariableNames(id1Variable, variable.Name) && !MatchVariableNames(id2Variable, variable.Name))
					{
						IVariableSpecification variableSpecification3 = FindVariableSpecification(variable.Name, this, sentenceSpecification.Variables);
						if (variableSpecification3 != null)
						{
							sentenceSpecification.Variables.Remove(variableSpecification3);
						}
						sentenceSpecification.Variables.Add(variable);
					}
				}
			}
			return sentenceSpecification;
		}

		protected ISentenceSpecification GetSentenceForThreeIndices(IList<ISentenceSpecification> sentences, int index1, int index2, int index3)
		{
			IVariableDefinition id1Variable = Variables[0];
			IVariableDefinition id2Variable = Variables[1];
			IVariableDefinition id3Variable = Variables[2];
			ISentenceSpecification sentenceSpecification = null;
			foreach (ISentenceSpecification sentence in sentences)
			{
				IVariableSpecification variableSpecification = sentence.Variables.First((IVariableSpecification v) => MatchVariableNames(id1Variable, v.Name));
				IVariableSpecification variableSpecification2 = sentence.Variables.First((IVariableSpecification v) => MatchVariableNames(id2Variable, v.Name));
				IVariableSpecification variableSpecification3 = sentence.Variables.First((IVariableSpecification v) => MatchVariableNames(id3Variable, v.Name));
				if (Convert.ToInt32(variableSpecification.Value) != index1 || Convert.ToInt32(variableSpecification2.Value) != index2 || Convert.ToInt32(variableSpecification3.Value) != index3)
				{
					continue;
				}
				if (sentenceSpecification == null)
				{
					sentenceSpecification = sentence;
					continue;
				}
				foreach (IVariableSpecification variable in sentence.Variables)
				{
					if (!MatchVariableNames(id1Variable, variable.Name) && !MatchVariableNames(id2Variable, variable.Name) && !MatchVariableNames(id3Variable, variable.Name))
					{
						IVariableSpecification variableSpecification4 = FindVariableSpecification(variable.Name, this, sentenceSpecification.Variables);
						if (variableSpecification4 != null)
						{
							sentenceSpecification.Variables.Remove(variableSpecification4);
						}
						sentenceSpecification.Variables.Add(variable);
					}
				}
			}
			return sentenceSpecification;
		}
	}
	public class ShortStringScalarVariableDefinition : VariableDefinitionBase<string>
	{
		public override bool IsVector => false;

		public override bool IsPair => false;

		public override int StorageSize => 2;

		public ShortStringScalarVariableDefinition()
		{
			base.DefaultValue = "";
			base.UpperLimit = "";
			base.LowerLimit = "";
		}

		public override void ProcessVariable(ISentenceDefinition processor, IVariableSpecification specification, IAspenProblemData problemData = null)
		{
			string value = Convert.ToString(specification.Value);
			processor.AddShortStringValue(value);
		}

		public override void ProcessDefault(ISentenceDefinition processor, IAspenProblemData problemData = null)
		{
			string defaultValue = GetDefaultValue<string>();
			processor.AddShortStringValue(defaultValue);
		}
	}
