	public class SimpleSentenceDefinition : SentenceDefinitionBase
	{
		public override string Structure => "Simple";

		public override int GetFixedIntegerLength()
		{
			if (base.CountTKWs == 1)
			{
				return 0;
			}
			int num = base.Variables.Where((IVariableDefinition s) => !s.IsVector && !s.StoreAsDouble).Sum((IVariableDefinition v) => v.StorageSize);
			int num2 = base.Variables.Count((IVariableDefinition s) => s.IsVector);
			return num + 2 * num2;
		}

		public override int GetFixedRealLength()
		{
			if (base.CountTKWs == 1)
			{
				return 0;
			}
			return base.Variables.Where((IVariableDefinition s) => !s.IsVector && s.StoreAsDouble).Sum((IVariableDefinition v) => v.StorageSize);
		}

		public override void GetLocations(IDictionary<string, int> locations, ref int intOffset, ref int realOffset)
		{
			if (base.CountTKWs == 1)
			{
				return;
			}
			foreach (IVariableDefinition variable in base.Variables)
			{
				if (variable.IsVector)
				{
					locations.Add(GenerateLocationKey(variable), intOffset);
					intOffset += 2;
				}
				else if (variable.StoreAsDouble)
				{
					locations.Add(GenerateLocationKey(variable), realOffset--);
				}
				else
				{
					locations.Add(GenerateLocationKey(variable), intOffset);
					intOffset += variable.StorageSize;
				}
			}
		}

		public override void AddIntegerValue(int value)
		{
			_fixedIntegerArray.Add(value);
		}

		public override void AddIntegerVector(int[] values)
		{
			int num = values.Length;
			_fixedIntegerArray.Add(num);
			if (num > 0)
			{
				_fixedIntegerArray.Add(_integerOffset);
				values.ToList().ForEach(delegate(int i)
				{
					_variableIntegerArray.Add(i);
				});
				_integerOffset += num;
			}
			else
			{
				_fixedIntegerArray.Add(0);
			}
		}

		public override void AddLongStringValue(string value, IAspenProblemData problemData = null)
		{
			if (value == "MISSING" || value == string.Empty)
			{
				_fixedIntegerArray.Add(100000123);
				return;
			}
			_fixedIntegerArray.Add(100000123);
			_stringBeadDictionary.Add(_fixedIntegerArray.Count, value.Holleriths());
		}

		public override void AddLongStringVector(string[] values, IAspenProblemData problemData = null)
		{
			int startBead = 100000120;
			int num = values.Length;
			_fixedIntegerArray.Add(num);
			if (num > 0)
			{
				_fixedIntegerArray.Add(_integerOffset);
				values.ToList().ForEach(delegate
				{
					_variableIntegerArray.Add(startBead++);
				});
				int stringOffset = _integerOffset;
				values.ToList().ForEach(delegate(string i)
				{
					_stringBeadDictionary.Add(stringOffset++, i.Holleriths());
				});
				_integerOffset += num;
			}
			else
			{
				_fixedIntegerArray.Add(0);
			}
		}

		public override void AddRealValue(double value)
		{
			_fixedRealArray.Add(value);
		}

		public override void AddRealVector(double[] values)
		{
			int num = values.Length;
			_fixedIntegerArray.Add(num);
			if (num > 0)
			{
				_fixedIntegerArray.Add(_realOffset);
				values.ToList().ForEach(delegate(double i)
				{
					_variableRealArray.Add(i);
				});
				_realOffset += num;
			}
			else
			{
				_fixedIntegerArray.Add(0);
			}
		}

		public override void AddShortStringValue(string value)
		{
			int[] array = value.Holleriths(2);
			_fixedIntegerArray.Add(array[0]);
			_fixedIntegerArray.Add(array[1]);
		}

		public override void AddShortStringVector(string[] values)
		{
			int num = values.Length;
			_fixedIntegerArray.Add(num);
			if (num > 0)
			{
				_fixedIntegerArray.Add(_integerOffset);
				for (int i = 0; i < values.Length; i++)
				{
					int[] array = values[i].Holleriths(2);
					_variableIntegerArray.Add(array[0]);
					_variableIntegerArray.Add(array[1]);
				}
				_integerOffset += 2 * num;
			}
			else
			{
				_fixedIntegerArray.Add(0);
			}
		}

		public override void DefaultSentence(int integerOffset, int realOffset)
		{
			_integerOffset = integerOffset;
			_realOffset = realOffset;
			foreach (IVariableDefinition variable in base.Variables)
			{
				ProcessVariableDefault(variable);
			}
			_integerOffset = 0;
			_realOffset = 0;
		}

		public override void DefaultSentence(int integerOffset, int realOffset, IAspenProblemData caseData)
		{
			_integerOffset = integerOffset;
			_realOffset = realOffset;
			foreach (IVariableDefinition variable in base.Variables)
			{
				ProcessVariableDefault(variable, caseData);
			}
			_integerOffset = 0;
			_realOffset = 0;
		}

		public override void ProcessSentence(IList<ISentenceSpecification> sentences, int integerOffset, int realOffset)
		{
			_numberOfSentences = 1;
			_integerOffset = integerOffset;
			_realOffset = realOffset;
			ISentenceSpecification sentenceSpecification = PackSimpleSentences(sentences);
			foreach (IVariableDefinition variableDefinition in base.Variables)
			{
				if (sentenceSpecification.Variables.Any((IVariableSpecification v) => v.Name == variableDefinition.TKWName))
				{
					IVariableSpecification variableSpecification = sentenceSpecification.Variables.First((IVariableSpecification v) => MatchVariableNames(variableDefinition, v.Name));
