	public abstract class VariableDefinitionBase<T> : IVariableDefinition
	{
		protected const int _integerMissing = 99999999;

		protected const double _realMising = 1E+35;

		public string TKWName { get; set; }

		public string AlternateTKWName { get; set; }

		public string TKWAbbreviationName { get; set; }

		public virtual bool StoreAsDouble => false;

		public abstract int StorageSize { get; }

		public int DataType1 { get; set; }

		public int DataType2 { get; set; }

		public VariableLimitOpCode VarLimitOp { get; set; }

		public int VarLimitGroup { get; set; }

		public int VarLimitQual { get; set; }

		public int VarLimitConstant { get; set; }

		public IVariableLimitCalculator VariableLimitCalculator { get; set; }

		public abstract bool IsVector { get; }

		public abstract bool IsPair { get; }

		public bool SymbolHasDefinedIntegerPair { get; set; }

		public int PairFlag { get; set; }

		public int VectorScalarFlag { get; set; }

		public int UnitConv { get; set; }

		public int DefaultRule { get; set; }

		public int EditFlag { get; set; }

		public int IntegerUpperLimit { get; set; }

		public int IntegerLowerLimit { get; set; }

		public int IntegerDefault { get; set; }

		public double RealUpperLimit { get; set; }

		public double RealLowerLimit { get; set; }

		public double RealDefault { get; set; }

		public string CharDefault { get; set; }

		public T DefaultValue { get; set; }

		public T UpperLimit { get; set; }

		public T LowerLimit { get; set; }

		public virtual V GetUpperLimit<V>()
		{
			if (typeof(V) == typeof(int) && IntegerUpperLimit != 0)
			{
				return (V)Convert.ChangeType(IntegerUpperLimit, typeof(V));
			}
			if (typeof(V) == typeof(double) && RealUpperLimit != 0.0)
			{
				return (V)Convert.ChangeType(RealUpperLimit, typeof(V));
			}
			if (typeof(V) == typeof(string))
			{
				return (V)Convert.ChangeType("", typeof(V));
			}
			if (typeof(V) == typeof(T))
			{
				return (V)Convert.ChangeType(UpperLimit, typeof(V));
			}
			throw new InvalidCastException();
		}

		public int GetIntegerUpperLimit(IAspenProblemData problemData, int[] intArray)
		{
			IntegerUpperLimit = problemData.PropertyPackage.ComponentIds.Count();
			return IntegerUpperLimit;
		}

		public virtual V GetLowerLimit<V>()
		{
			if (typeof(V) == typeof(int) && IntegerLowerLimit != 0)
			{
				return (V)Convert.ChangeType(IntegerLowerLimit, typeof(V));
			}
			if (typeof(V) == typeof(double) && RealLowerLimit != 0.0)
			{
				return (V)Convert.ChangeType(RealLowerLimit, typeof(V));
			}
			if (typeof(V) == typeof(string))
			{
				return (V)Convert.ChangeType("", typeof(V));
			}
			if (typeof(V) == typeof(T))
			{
				return (V)Convert.ChangeType(LowerLimit, typeof(V));
			}
			throw new InvalidCastException();
		}

		public V GetDefaultValue<V>()
		{
			if (DefaultRule == 1)
			{
				throw new ArgumentException("DefaultRule == 1; Default Setting Value NOT allowed. Value MUST be specified.");
			}
			if (typeof(V) == typeof(int) && IntegerDefault != 0)
			{
				return (V)Convert.ChangeType(IntegerDefault, typeof(V));
			}
			if (typeof(V) == typeof(double) && RealDefault != 0.0)
			{
				return (V)Convert.ChangeType(RealDefault, typeof(V));
			}
			if (typeof(V) == typeof(T))
			{
				return (V)Convert.ChangeType(DefaultValue, typeof(V));
			}
			throw new InvalidCastException();
		}

		public void Report(StreamWriter writer)
		{
			writer.WriteLine("Variable \"{0}\" Alternate: \"{1}\", Short: \"{2}\"", TKWName, AlternateTKWName, TKWAbbreviationName);
		}

		public abstract void ProcessDefault(ISentenceDefinition processor, IAspenProblemData problemData = null);

		public virtual void ProcessVariable(ISentenceDefinition processor, IVariableSpecification specification, IAspenProblemData problemData = null)
		{
			int defaultValue = GetDefaultValue<int>();
			defaultValue = ((!(specification.Value is int num)) ? ConvertDataValue(problemData, specification.Value) : num);
			StoreIntegerValue(processor, defaultValue);
		}

		public int ComputeLimit(IAspenProblemData problemData = null)
		{
			if (VariableLimitCalculator == null)
			{
				VariableLimitCalculator = VariableLimitCalculatorFactory.CreateLimitCalculator(VarLimitGroup, VarLimitQual, VarLimitOp, VarLimitConstant);
			}
			if (problemData == null)
			{
				int upperLimit = GetUpperLimit<int>();
				if (upperLimit == int.MaxValue)
				{
					return 4;
				}
				if ((double)upperLimit == double.MaxValue)
				{
					return 2;
				}
				return upperLimit;
			}
			return VariableLimitCalculator.CalculateLimit(problemData);
		}

		protected virtual int ConvertDataValue(IAspenProblemData problemData, object value)
		{
			return SpecificationToInteger(value);
		}

		protected int SpecificationToInteger(object specification)
		{
			if (!(specification is double[] array))
			{
				if (!(specification is double value))
				{
					if (!(specification is string[] array2))
					{
						if (!(specification is string s))
						{
							if (specification is int[] array3)
							{
								return array3[0];
							}
							return (int)specification;
						}
						return StringToInteger(s);
					}
					return StringToInteger(array2[0]);
				}
				return Convert.ToInt32(value);
			}
			return Convert.ToInt32(array[0]);
		}

		protected void StoreIntegerValue(ISentenceDefinition sentence, int value)
		{
			sentence.AddIntegerValue(value);
		}

		protected double StringToDouble(string s)
		{
			if (double.TryParse(s, out var result))
			{
				return result;
			}
			if (double.TryParse(s.Replace('D', 'E'), NumberStyles.Any, CultureInfo.InvariantCulture, out result))
			{
				return result;
			}
			return Convert.ToDouble(s);
		}

		protected int StringToInteger(string s)
		{
			if (int.TryParse(s, out var result))
			{
				return result;
			}
			if (double.TryParse(s, out var result2))
			{
				return Convert.ToInt32(result2);
			}
			return Convert.ToInt32(s);
		}

		protected string[] ConvertSpecificationsToStrings(object specification)
		{
			string[] values = new string[0];
			double[] array = specification as double[];
			if (array == null)
			{
				if (!(specification is double num))
				{
					string[] array2 = specification as string[];
					if (array2 == null)
					{
						if (!(specification is string text))
						{
							int[] array3 = specification as int[];
							if (array3 == null)
							{
								if (specification is int num2)
								{
									values = new string[1];
									values[0] = $"{num2}";
								}
								else
								{
									values = (string[])specification;
								}
							}
							else
							{
								values = new string[array3.Length];
								Enumerable.Range(0, array3.Length).ToList().ForEach(delegate(int i)
								{
									values[i] = $"{array3[i]}";
								});
							}
						}
						else
						{
							values = new string[1];
							values[0] = text;
						}
					}
					else
					{
						values = new string[array2.Length];
						Enumerable.Range(0, array2.Length).ToList().ForEach(delegate(int i)
						{
							values[i] = array2[i];
						});
					}
				}
				else
				{
					values = new string[1];
					values[0] = $"{num}";
				}
			}
			else
			{
				values = new string[array.Length];
				Enumerable.Range(0, array.Length).ToList().ForEach(delegate(int i)
				{
					values[i] = $"{array[i]}";
				});
			}
			return values;
		}
	}
	public abstract class VariableLimitCalculatorBase : IVariableLimitCalculator
	{
		internal int _legacyAPGroup;

		internal int _legacyAPQual;

		internal VariableLimitOpCode _OpCode;

		internal int _VarLimitConstant;

		public VariableLimitOpCode OpCode => _OpCode;

		public virtual int CalculateLimit(IAspenProblemData problemData = null)
		{
			switch (_OpCode)
			{
			case VariableLimitOpCode.None:
				if (_VarLimitConstant > 0)
				{
					return _VarLimitConstant;
				}
				return InternalCalculate(problemData);
			case VariableLimitOpCode.Add:
				return _VarLimitConstant + InternalCalculate(problemData);
			case VariableLimitOpCode.Multiply:
				return _VarLimitConstant * InternalCalculate(problemData);
			case VariableLimitOpCode.AlwaysAllocateVectorInBead:
				return InternalCalculate(problemData);
			case VariableLimitOpCode.Special:
				return 0;
			default:
				return 0;
			}
		}

		protected virtual int InternalCalculate(IAspenProblemData problemData)
		{
			return 1;
		}
	}
