	public class VariableLimitCalculateByComponent : VariableLimitCalculatorBase
	{
		public enum VariableLimitComponentType
		{
			None,
			Conventional,
			Nonconventional,
			Total,
			AttributedComponents,
			AttributedConventionalComponents
		}

		private readonly VariableLimitComponentType ComponentType;

		public VariableLimitCalculateByComponent(int QUALIFIER = 0, int CONSTANT = 0, VariableLimitOpCode OPCODE = VariableLimitOpCode.None)
		{
			_VarLimitConstant = CONSTANT;
			_OpCode = OPCODE;
			switch (QUALIFIER)
			{
			case 1:
				ComponentType = VariableLimitComponentType.Conventional;
				break;
			case 2:
				ComponentType = VariableLimitComponentType.Nonconventional;
				break;
			case 3:
				ComponentType = VariableLimitComponentType.Total;
				break;
			case 4:
				ComponentType = VariableLimitComponentType.AttributedComponents;
				break;
			case 5:
				ComponentType = VariableLimitComponentType.AttributedConventionalComponents;
				break;
			}
		}

		protected override int InternalCalculate(IAspenProblemData problemData)
		{
			if (ComponentType == VariableLimitComponentType.None)
			{
				return 1;
			}
			if (ComponentType == VariableLimitComponentType.Conventional)
			{
				return problemData.GensenInformation.NumberOfComponents.Conventional;
			}
			if (ComponentType == VariableLimitComponentType.Nonconventional)
			{
				return problemData.GensenInformation.NumberOfComponents.NonConventional;
			}
			if (ComponentType == VariableLimitComponentType.Total)
			{
				return problemData.GensenInformation.NumberOfComponents.All;
			}
			if (ComponentType == VariableLimitComponentType.AttributedComponents)
			{
				return problemData.GensenInformation.NumberOfComponents.Attributed;
			}
			if (ComponentType == VariableLimitComponentType.AttributedConventionalComponents)
			{
				return problemData.GensenInformation.NumberOfComponents.AttributedConventional;
			}
			return 0;
		}
	}
