	public abstract class WorkAreaDefinitionBase : IWorkAreaDefinition
	{
		public string AreaName { get; set; }

		public VariableLimitOpCode Dimension1OpCode { get; set; }

		public int Dimension1Group { get; set; }

		public int Dimension1Qual { get; set; }

		public int Dimension1Constant { get; set; }

		public VariableLimitOpCode Dimension2OpCode { get; set; }

		public int Dimension2Group { get; set; }

		public int Dimension2Qual { get; set; }

		public int Dimension2Constant { get; set; }

		public IVariableLimitCalculator Dimension1VariableLimitCalculator { get; set; }

		public IVariableLimitCalculator Dimension2VariableLimitCalculator { get; set; }

		public int ComputeWorkAreaSize(IAspenProblemData aspenProblemData = null)
		{
			if (Dimension1VariableLimitCalculator == null)
			{
				Dimension1VariableLimitCalculator = VariableLimitCalculatorFactory.CreateLimitCalculator(Dimension1Group, Dimension1Qual, Dimension1OpCode, Dimension1Constant);
			}
			if (Dimension2VariableLimitCalculator == null)
			{
				Dimension2VariableLimitCalculator = VariableLimitCalculatorFactory.CreateLimitCalculator(Dimension2Group, Dimension2Qual, Dimension2OpCode, Dimension2Constant);
			}
			int num = Dimension1VariableLimitCalculator.CalculateLimit(aspenProblemData);
			int num2 = Dimension2VariableLimitCalculator.CalculateLimit(aspenProblemData);
			return num * num2;
		}
	}
