	internal class DummyDataTypeBase : VariableDefinitionBase<int>
	{
		public override int StorageSize => 1;

		public override bool IsVector => false;

		public override bool IsPair => false;

		public override void ProcessDefault(ISentenceDefinition processor, IAspenProblemData problemData = null)
		{
			int defaultValue = GetDefaultValue<int>();
			processor.AddIntegerValue(defaultValue);
		}

		public override void ProcessVariable(ISentenceDefinition processor, IVariableSpecification specification, IAspenProblemData problemData = null)
		{
			int value = ConvertSpecifications(specification.Value);
			processor.AddIntegerValue(value);
		}

		private int ConvertSpecifications(object specification)
		{
			if (!(specification is double[] array))
			{
				if (!(specification is double value))
				{
					if (!(specification is string[] array2))
					{
						if (!(specification is string s))
						{
							if (specification is int[] array3)
							{
								return array3[0];
							}
							return (int)specification;
						}
						return StringToInteger(s);
					}
					return StringToInteger(array2[0]);
				}
				return Convert.ToInt32(value);
			}
			return Convert.ToInt32(array[0]);
		}
	}
