	public class ComponentVariableDefinition : VariableDefinitionBase<int>
	{
		public override int StorageSize => 1;

		public override bool IsVector => false;

		public override bool IsPair => false;

		protected override int ConvertDataValue(IAspenProblemData problemData, object value)
		{
			string item = (string)value;
			return problemData.PropertyPackage.ComponentIds.ToList().IndexOf(item) + 1;
		}

		public static int GetIntegerUpperLimit(IAspenProblemData problemData)
		{
			return problemData.PropertyPackage.ComponentIds.Length;
		}

		public override void ProcessDefault(ISentenceDefinition processor, IAspenProblemData problemData = null)
		{
			int defaultValue = GetDefaultValue<int>();
			processor.AddIntegerValue(defaultValue);
		}

		public override void ProcessVariable(ISentenceDefinition processor, IVariableSpecification specification, IAspenProblemData problemData = null)
		{
			int value = GetDefaultValue<int>();
			if (specification.Value is int num)
			{
				value = num;
			}
			else if (problemData != null)
			{
				value = ConvertDataValue(problemData, specification.Value);
			}
			StoreIntegerValue(processor, value);
		}

		public override V GetUpperLimit<V>()
		{
			if (typeof(V) == typeof(int) && base.IntegerUpperLimit != 0)
			{
				return (V)Convert.ChangeType(base.IntegerUpperLimit, typeof(V));
			}
			if (typeof(V) == typeof(double) && base.RealUpperLimit != 0.0)
			{
				return (V)Convert.ChangeType(base.RealUpperLimit, typeof(V));
			}
			if (typeof(V) == typeof(string))
			{
				return (V)Convert.ChangeType("", typeof(V));
			}
			if (typeof(V) == typeof(V))
			{
				return (V)Convert.ChangeType(base.UpperLimit, typeof(V));
			}
			throw new InvalidCastException();
		}
	}
